int append_line_safe(char *dst, size_t dst_size, const char *line)
{
    size_t used;

    if (dst == NULL || line == NULL) {
        return -1;
    }

    used = strlen(dst);
    if (used + strlen(line) + 2 > dst_size) {
        return -1;
    }

    strncat(dst, line, dst_size - used - 1);
    strncat(dst, "\n", dst_size - strlen(dst) - 1);
    return 0;
}

