int parse_tlv_safe(const unsigned char *buf, size_t buf_len, tlv_t *out)
{
    size_t offset = 2;
    size_t declared;

    if (buf == NULL || out == NULL || buf_len < 2) {
        return -1;
    }

    out->type = buf[0];
    declared = buf[1];

    if (declared > buf_len - offset) {
        return -1;
    }

    out->len = declared;
    out->value = (unsigned char *)(buf + offset);
    out->total = declared + offset;

    return 0;
}

