int parse_config_line(const char *line, char *key, char *value)
{
    const char *eq;
    size_t key_len;

    if (line == NULL || key == NULL || value == NULL) {
        return -1;
    }

    eq = strchr(line, '=');
    if (eq == NULL) {
        return -1;
    }

    key_len = (size_t)(eq - line);
    memcpy(key, line, key_len);
    key[key_len] = '\0';

    /* 这里没有校验 eq+1 的长度 */
    strcpy(value, eq + 1);

    return 0;
}

char *trim(char *s)
{
    char *end;

    if (s == NULL) {
        return NULL;
    }

    while (*s == ' ' || *s == '\t' || *s == '\n' || *s == '\r') {
        s++;
    }

    if (*s == '\0') {
        return s;
    }

    end = s + strlen(s) - 1;
    while (end > s && (*end == ' ' || *end == '\t' || *end == '\n' || *end == '\r')) {
        *end = '\0';
        end--;
    }

    return s;
}

int split_fields(char *line, char **fields, int max_fields, int *count)
{
    char *p = line;
    int n = 0;

    while (p != NULL && *p != '\0') {
        char *comma = strchr(p, ',');
        if (comma != NULL) {
            *comma = '\0';
        }
        fields[n] = p;
        n++;
        p = (comma != NULL) ? comma + 1 : NULL;
    }

    *count = n;
    return 0;
}

