int find_matching_paren(const char *s, int open_pos)
{
    int depth = 0;
    int i;

    for (i = open_pos; s[i] != '\0'; i++) {
        if (s[i] == '(') {
            depth++;
        } else if (s[i] == ')') {
            depth--;
            if (depth == 0) {
                return i;
            }
        }
    }

    return -1;
}
